import os, json

def transform(input_grid):
    """
    Pattern:
    - Grid divided by row/col lines (fully 8 rows/cols) into sections
    - Non-zero/non-8 cells are "markers" 
    - Each section gets a value from its marker OR from adjacent sections with markers
    - 6 appears between two sections with marker value X (separator)
    """
    H, W = len(input_grid), len(input_grid[0])

    # Find which cells are on line positions (fully 8)
    row_lines = set(r for r in range(H) if all(input_grid[r][c] == 8 for c in range(W)))
    col_lines = set(c for c in range(W) if all(input_grid[r][c] == 8 for r in range(H)))

    # Build row section indices
    row_section_of = {}
    curr = 0
    for r in range(H):
        if r in row_lines:
            curr = r + 1
        else:
            row_section_of[r] = curr - 1 if curr > 0 else 0

    col_section_of = {}
    curr = 0
    for c in range(W):
        if c in col_lines:
            curr = c + 1
        else:
            col_section_of[c] = curr - 1 if curr > 0 else 0

    # Find markers per section
    section_markers = {}
    for r in range(H):
        if r in row_lines:
            continue
        for c in range(W):
            if c in col_lines:
                continue
            val = input_grid[r][c]
            if val not in (0, 8):
                rs = row_section_of[r]
                cs = col_section_of[c]
                if (rs, cs) not in section_markers:
                    section_markers[(rs, cs)] = val

    # Build output
    output = [[0]*W for _ in range(H)]

    for r in range(H):
        if r in row_lines:
            output[r] = [8]*W
            continue

        for c in range(W):
            if c in col_lines:
                output[r][c] = 8
                continue

            rs = row_section_of[r]
            cs = col_section_of[c]
            marker_val = section_markers.get((rs, cs))

            if marker_val is not None:
                output[r][c] = marker_val
            else:
                # Propagate from neighbors
                neighbors = []
                if rs > 0:
                    neighbors.append((rs-1, cs))
                if rs < H-1:
                    neighbors.append((rs+1, cs))
                if cs > 0:
                    neighbors.append((rs, cs-1))
                if cs < W-1:
                    neighbors.append((rs, cs+1))

                for (nr, nc) in neighbors:
                    if (nr, nc) in section_markers:
                        output[r][c] = section_markers[(nr, nc)]
                        break

    return output

