# Now write the working transform that properly handles everything
import os, json

def transform(input_grid):
    H, W = len(input_grid), len(input_grid[0])

    row_lines_set = set(r for r in range(H) if all(input_grid[r][c] == 8 for c in range(W)))
    col_lines_set = set(c for c in range(W) if all(input_grid[r][c] == 8 for r in range(H)))

    # Build mapping: row_group_of[r] = row group number for row r (if r is not a line)
    row_group_of = {}
    curr = 0
    for r in range(H):
        if r in row_lines_set:
            curr = r + 1
        else:
            row_group_of[r] = curr - 1 if curr > 0 else 0

    col_group_of = {}
    curr = 0
    for c in range(W):
        if c in col_lines_set:
            curr = c + 1
        else:
            col_group_of[c] = curr - 1 if curr > 0 else 0

    # Find markers by section
    section_markers = {}  # row_group -> {col_group: val, ...}
    for r in range(H):
        if r in row_lines_set:
            continue
        sr = row_group_of[r]
        for c in range(W):
            if c in col_lines_set:
                continue
            sc = col_group_of[c]
            val = input_grid[r][c]
            if val not in (0, 8):
                if sr not in section_markers:
                    section_markers[sr] = {}
                if sc not in section_markers[sr]:
                    section_markers[sr][sc] = val

    # Build output
    output = [[0]*W for _ in range(H)]

    for r in range(H):
        if r in row_lines_set:
            output[r] = [8]*W
            continue

        sr = row_group_of[r]
        for c in range(W):
            if c in col_lines_set:
                output[r][c] = 8
                continue

            sc = col_group_of[c]

            # Check if this section has a marker
            marker_val = section_markers[sr].get(sc)

            if marker_val is not None:
                output[r][c] = marker_val
            else:
                # Check if this section is BETWEEN two marked sections with SAME value
                # This creates a 6 separator
                h_val = section_markers[sr].get(sc-1) if (sc-1) in section_markers[sr] else None
                h_next = section_markers[sr].get(sc+1) if (sc+1) in section_markers[sr] else None

                # Check horizontal: if between same-value markers, output 6
                if h_val is not None and h_next is not None:
                    if h_val == h_next:
                        output[r][c] = 6
                        continue

                # Propagate from adjacent marked section
                if h_val is not None:
                    output[r][c] = h_val
                elif h_next is not None:
                    output[r][c] = h_next
                else:
                    # No adjacent marked neighbor
                    output[r][c] = 0

    return output

