def transform(input_grid):
    """
    Transform function for task-dfb204af:
    - Grid is divided into sections by row/col lines of 8s
    - Each section with a marker gets that marker value
    - Sections between same-value markers in same row_group get 6
    - Sections without adjacent markers get 0
    """
    H, W = len(input_grid), len(input_grid[0])

    row_lines_set = set(r for r in range(H) if all(input_grid[r][c] == 8 for c in range(W)))
    col_lines_set = set(c for c in range(W) if all(input_grid[r][c] == 8 for r in range(H)))

    # Build row/col group mappings
    row_group_of = {}
    curr = 0
    for r in range(H):
        if r in row_lines_set:
            curr = r + 1
        else:
            row_group_of[r] = curr - 1 if curr > 0 else 0

    col_group_of = {}
    curr = 0
    for c in range(W):
        if c in col_lines_set:
            curr = c + 1
        else:
            col_group_of[c] = curr - 1 if curr > 0 else 0

    # Find markers by section
    section_markers = {}  # row_group -> {col_group: value, ...}
    for r in range(H):
        if r in row_lines_set:
            continue
        sr = row_group_of[r]
        if sr not in section_markers:
            section_markers[sr] = {}
        for c in range(W):
            if c in col_lines_set:
                continue
            sc = col_group_of[c]
            val = input_grid[r][c]
            if val not in (0, 8):
                if sc not in section_markers[sr]:
                    section_markers[sr][sc] = val

    # Build output
    output = [[0]*W for _ in range(H)]

    for r in range(H):
        if r in row_lines_set:
            output[r] = [8]*W
            continue

        sr = row_group_of[r]
        for c in range(W):
            if c in col_lines_set:
                output[r][c] = 8
                continue

            sc = col_group_of[c]

            # If this section has a marker, use it
            if sr in section_markers and sc in section_markers[sr]:
                output[r][c] = section_markers[sr][sc]
            # Otherwise, propagate horizontally from adjacent marked sections
            elif sr in section_markers:
                h_left = section_markers[sr].get(sc-1)
                h_right = section_markers[sr].get(sc+1)
                if h_left is not None:
                    output[r][c] = h_left
                elif h_right is not None:
                    output[r][c] = h_right
                else:
                    output[r][c] = 0

    return output

